import { field, select, checkbox, textarea, htmlEscape } from "../tool-core.js";export default {form: `<div class="field-grid">${field({ id: "tiValue", label: "Indent amount", type: "number", value: "2" })}${select({ id: "tiUnit", label: "Unit", options: [{label:"em",value:"em"},{label:"rem",value:"rem"},{label:"px",value:"px"},{label:"ch",value:"ch"},{label:"%",value:"percent"}], value: "em" })}</div><div class="field-grid">${checkbox({ id: "tiHanging", label: "hanging (reverse indent — indent all lines except the first)", checked: true })}${checkbox({ id: "tiEachLine", label: "each-line (indent every line after a forced break)", checked: false })}</div><div class="field-grid">${field({ id: "tiSelector", label: "CSS selector", value: "p" })}${checkbox({ id: "tiFallback", label: "Include fallback without hanging/each-line", checked: true })}</div><div class="field-grid">${textarea({ id: "tiSample", label: "Sample text for preview", value: "This is the first line of the paragraph. The hanging indent means this line stays at the left edge.", full: true })}</div>`,generate(root) {const value = root.querySelector("#tiValue").value || "2";const unit = root.querySelector("#tiUnit").value;const unitStr = unit === "percent" ? "%" : unit;const hanging = root.querySelector("#tiHanging").checked;const eachLine = root.querySelector("#tiEachLine").checked;const selector = root.querySelector("#tiSelector").value.trim() || "p";const fallback = root.querySelector("#tiFallback").checked;const sample = root.querySelector("#tiSample").value.trim() || "Sample paragraph text for preview.";const indentVal = `${value}${unitStr}`;const keywords = [];if (hanging) keywords.push("hanging");if (eachLine) keywords.push("each-line");const tiValue = keywords.length ? `${indentVal} ${keywords.join(" ")}` : indentVal;const lines = [];lines.push("/* CSS text-indent with hanging / each-line — Baseline 2026 */");lines.push("/* Browser support: Chrome 130+, Edge 130+, Safari 18.2+, Firefox 135+ */");lines.push("");lines.push(`${selector} {`);if (fallback) lines.push(` text-indent: ${indentVal}; /* fallback */`);lines.push(` text-indent: ${tiValue};`);lines.push("}");lines.push("");if (hanging) {lines.push("/* hanging: indents all lines EXCEPT the first line. */");lines.push("/* Useful for hanging punctuation, bibliography entries, and definition lists. */");}if (eachLine) {lines.push("/* each-line: applies indentation after every forced line break (<br> or \\n). */");lines.push("/* Without each-line, text-indent only applies to the first formatted line. */");}lines.push("");lines.push("/* Fallback for older browsers: */");lines.push(`/* Use padding-left + text-indent: -${indentVal} to simulate hanging indent */`);const previewStyle = `text-indent:${tiValue};padding:12px;background:#fff;border:1px solid #d1d5db;border-radius:8px;max-width:500px;line-height:1.6;font-size:15px`;const previewText = sample.replace(/\n/g, "<br>");const keywordTags = [];if (hanging) keywordTags.push("hanging");if (eachLine) keywordTags.push("each-line");const preview = `<div><div style="font-size:12px;margin-bottom:8px;color:#374151;font-weight:600">text-indent: ${tiValue}${keywordTags.length ? `<span style="font-weight:400;color:#6b7280;margin-left:4px">(${keywordTags.join(" + ")})</span>` : ""}</div><div style="${previewStyle}">${previewText}</div><div style="margin-top:8px;font-size:11px;color:#6b7280">${hanging ? "&#9654; hanging: all lines after the first are indented | " : ""}${eachLine ? "&#9654; each-line: every line after a &lt;br&gt; is indented" : ""}</div></div>`;return { output: lines.join("\n"), preview };}};